#!/bin/bash
python3 - <<'ATPY'

import base64, json, mimetypes, os, subprocess, sys, time, urllib.error, urllib.request, uuid

API_KEY = os.environ.get("VAR_LTX_API_KEY") or os.environ.get("VAR_LTX_KEY") or ""
WORK_DIR = os.environ.get("AT_WORK_DIR") or "/tmp"
BASE_URL = "https://api.ltx.io"

def die(message, **extra):
    out = {"error": message}
    out.update(extra)
    print(json.dumps(out)); sys.exit(0)

if not API_KEY:
    die("LTX API key not configured (create an LTX connection with ltx_api_key)")

def uid():
    return uuid.uuid4().hex[:10]

def arg(name, default=""):
    return os.environ.get("ARG_" + name, "") or default

def arg_bool(name, default=True):
    raw = os.environ.get("ARG_" + name, "").strip().lower()
    if not raw:
        return default
    return raw not in ("false", "0", "no", "off")

def arg_int(name, default=None):
    raw = os.environ.get("ARG_" + name, "")
    if not raw:
        return default
    try:
        return int(float(raw))
    except ValueError:
        die(name.lower() + " must be a number, got %r" % raw)

def request_json(path, payload=None, method=None, timeout=60):
    data = json.dumps(payload).encode() if payload is not None else None
    req = urllib.request.Request(BASE_URL + path, data=data,
        method=method or ("POST" if data is not None else "GET"),
        headers={"Authorization": "Bearer " + API_KEY,
                 "Content-Type": "application/json"})
    try:
        with urllib.request.urlopen(req, timeout=timeout) as resp:
            return json.load(resp)
    except urllib.error.HTTPError as e:
        detail = e.read().decode("utf-8", "replace")[:1000]
        try:
            parsed = json.loads(detail)
            message = parsed.get("message") or parsed.get("error", {}).get("message") or detail
            error_type = parsed.get("type") or parsed.get("error", {}).get("type")
        except ValueError:
            message, error_type = detail, ""
        die("LTX API HTTP %d: %s" % (e.code, message), error_type=error_type)
    except urllib.error.URLError as e:
        die("LTX API request failed: %s" % e.reason)

def upload_local(path):
    """Upload a local file through LTX /v1/upload and return ltx:// storage URI."""
    p = os.path.expanduser(path)
    if not os.path.isfile(p):
        die("input file not found: " + p)
    info = request_json("/v1/upload", payload=None, method="POST", timeout=30)
    upload_url = info.get("upload_url") or ""
    storage_uri = info.get("storage_uri") or ""
    if not upload_url or not storage_uri:
        die("LTX upload initialization returned no upload_url/storage_uri", raw=str(info)[:600])
    headers = {str(k): str(v) for k, v in (info.get("required_headers") or {}).items()}
    headers.setdefault("Content-Type", mimetypes.guess_type(p)[0] or "application/octet-stream")
    blob = open(p, "rb").read()
    try:
        req = urllib.request.Request(upload_url, data=blob, headers=headers, method="PUT")
        with urllib.request.urlopen(req, timeout=900):
            pass
    except urllib.error.HTTPError as e:
        die("LTX storage upload failed: HTTP %d" % e.code,
            detail=e.read().decode("utf-8", "replace")[:500])
    except urllib.error.URLError as e:
        die("LTX storage upload failed: %s" % e.reason)
    return storage_uri

def media_uri(ref):
    if not ref:
        return ""
    if ref.startswith(("https://", "data:", "ltx://")):
        return ref
    if ref.startswith("http://"):
        die("LTX accepts public HTTPS URLs only (not HTTP): " + ref)
    return upload_local(ref)

def resolution_pixels(tier, aspect):
    aliases = {
        "1280x720": "1280x720", "720x1280": "720x1280",
        "1920x1080": "1920x1080", "1080x1920": "1080x1920",
        "2560x1440": "2560x1440", "1440x2560": "1440x2560",
        "3840x2160": "3840x2160", "2160x3840": "2160x3840",
    }
    if tier in aliases:
        return tier
    landscape = aspect != "9:16"
    pairs = {
        "720p": ("1280x720", "720x1280"),
        "1080p": ("1920x1080", "1080x1920"),
        "1440p": ("2560x1440", "1440x2560"),
        "4k": ("3840x2160", "2160x3840"),
        "2160p": ("3840x2160", "2160x3840"),
    }
    key = tier.lower()
    if key not in pairs:
        die("resolution must be 720p, 1080p, 1440p, 4K, or an exact supported WIDTHxHEIGHT")
    return pairs[key][0 if landscape else 1]

def validate_matrix(variant, resolution, fps, duration, automatic):
    short = resolution in ("1280x720", "720x1280", "1920x1080", "1080x1920")
    if variant == "pro":
        if not short:
            die("LTX-2.5 Pro supports 720p/1080p only; use variant=fast for 1440p/4K")
        if fps not in (24, 25, 50):
            die("LTX-2.5 Pro fps must be 24, 25, or 50")
        allowed = (6, 8, 10)
    else:
        if fps not in (24, 25, 48, 50):
            die("LTX-2.5 Fast fps must be 24, 25, 48, or 50")
        allowed = (6, 8, 10, 12, 14, 16, 18, 20) if short and fps in (24, 25) else (6, 8, 10)
    if not automatic and duration not in allowed:
        die("unsupported duration for this model/resolution/fps", allowed_durations=list(allowed))

def local_audio_duration(ref):
    if not ref or ref.startswith(("https://", "data:", "ltx://")):
        return None
    p = os.path.expanduser(ref)
    probe = subprocess.run(["ffprobe", "-v", "error", "-show_entries", "format=duration",
                            "-of", "default=noprint_wrappers=1:nokey=1", p],
                           capture_output=True, text=True)
    try:
        return float(probe.stdout.strip())
    except ValueError:
        die("ffprobe could not read audio duration", stderr=(probe.stderr or "")[-400:])

def poll(endpoint, job_id, minutes=45):
    deadline = time.time() + minutes * 60
    while time.time() < deadline:
        time.sleep(5)
        status = request_json("/v2/%s/%s" % (endpoint, job_id), timeout=60)
        state = status.get("status")
        if state == "completed":
            return status
        if state == "failed":
            err = status.get("error") or {}
            die("LTX generation failed: %s" % (err.get("message") or "unknown error"),
                error_type=err.get("type"), job_id=job_id)
    die("LTX generation timed out", job_id=job_id,
        status_url=BASE_URL + "/v2/%s/%s" % (endpoint, job_id))

def download(url, output):
    req = urllib.request.Request(url)
    with urllib.request.urlopen(req, timeout=900) as resp, open(output, "wb") as f:
        while True:
            chunk = resp.read(1 << 20)
            if not chunk:
                break
            f.write(chunk)
    return os.path.getsize(output)

prompt = arg("PROMPT")
if not prompt:
    die("prompt is required")
style = arg("STYLE")
if style:
    prompt = prompt.rstrip() + " Visual style: " + style.strip()

variant = arg("VARIANT", "fast").lower()
if variant not in ("fast", "pro"):
    die("variant must be fast or pro")
model = "ltx-2-5-" + variant
start_image = arg("START_IMAGE")
end_image = arg("END_IMAGE")
audio = arg("AUDIO")
if end_image and not start_image:
    die("end_image requires start_image")

aspect = arg("ASPECT_RATIO", "16:9")
if aspect not in ("16:9", "9:16"):
    die("aspect_ratio must be 16:9 or 9:16")
resolution = resolution_pixels(arg("RESOLUTION", "1080p"), aspect)
fps = arg_int("FPS", 24)
camera = arg("CAMERA_MOTION")
if camera and camera not in ("dolly_in", "dolly_out", "dolly_left", "dolly_right", "jib_up", "jib_down", "static", "focus_shift"):
    die("unsupported camera_motion", allowed=["dolly_in", "dolly_out", "dolly_left", "dolly_right", "jib_up", "jib_down", "static", "focus_shift"])

if audio:
    endpoint = "audio-to-video"
    local_duration = local_audio_duration(audio)
    high_res = resolution not in ("1280x720", "720x1280", "1920x1080", "1080x1920")
    max_seconds = 10 if variant == "pro" or high_res else 20
    if local_duration is not None and (local_duration < 2 or local_duration > max_seconds + 0.05):
        die("audio duration %.2fs is outside LTX-2.5 %s limit (2-%ds for this model/resolution)" %
            (local_duration, variant, max_seconds))
    # Validate model/resolution/fps while ignoring explicit video duration.
    validate_matrix(variant, resolution, fps, 6, automatic=True)
    payload = {"audio_uri": media_uri(audio), "prompt": prompt, "model": model,
               "resolution": resolution, "fps": fps}
    if start_image:
        payload["image_uri"] = media_uri(start_image)
    if end_image:
        payload["last_frame_uri"] = media_uri(end_image)
    if camera:
        payload["camera_motion"] = camera
else:
    endpoint = "image-to-video" if start_image else "text-to-video"
    raw_duration = arg("DURATION", "auto").lower()
    automatic = raw_duration in ("auto", "null")
    if automatic and end_image:
        die("automatic duration cannot be combined with end_image; choose 6, 8, or 10 seconds")
    duration = None if automatic else arg_int("DURATION")
    validate_matrix(variant, resolution, fps, duration, automatic)
    payload = {"prompt": prompt, "model": model, "duration": duration,
               "resolution": resolution, "fps": fps,
               "generate_audio": arg_bool("GENERATE_AUDIO", True)}
    if start_image:
        payload["image_uri"] = media_uri(start_image)
    if end_image:
        payload["last_frame_uri"] = media_uri(end_image)
    if camera:
        payload["camera_motion"] = camera

submitted = request_json("/v2/" + endpoint, payload=payload, method="POST", timeout=90)
job_id = submitted.get("id") or ""
if not job_id:
    die("LTX submit returned no job id", raw=str(submitted)[:600])
status = poll(endpoint, job_id)
result = status.get("result") or {}
video_url = result.get("video_url") or ""
if not video_url:
    die("LTX completed without result.video_url", job_id=job_id, raw=str(status)[:800])
os.makedirs(WORK_DIR, exist_ok=True)
output = arg("OUTPUT") or os.path.join(WORK_DIR, "ltx25-%s.mp4" % uid())
if not os.path.isabs(output):
    output = os.path.join(WORK_DIR, output)
os.makedirs(os.path.dirname(output), exist_ok=True)
size = download(video_url, output)
print(json.dumps({"video_file": output, "video_url": video_url, "size_bytes": size,
                  "model": model, "endpoint": endpoint, "job_id": job_id,
                  "resolution": resolution, "fps": fps}))

ATPY
